def numeric_ssa(fn):
    definitions=list(fn["params"])
    for block in fn["blocks"]:
        definitions.extend(block["params"])
        for op in block["ops"]:definitions.extend(op["out"])
    names=[row["name"] for row in definitions]
    assert names and all(type(name) is str and name.startswith("v") and
        name[1:].isascii() and name[1:].isdecimal() for name in names)
    return max(int(name[1:]) for name in names)
